package strom.zio

import scala.util.Random
import _root_.zio.{Chunk, Ref, Runtime, UIO, Unsafe, ZIO, durationInt}
import _root_.zio.stream.ZStream

object FuzzSupport:
  final class Boom extends RuntimeException("boom")
  def ef(log: Ref[Vector[String]], tag: String, x: Int): UIO[Unit] = log.update(_ :+ s"$tag:$x")

/** Random ZStream operator chains (generated by project/FuzzGen.scala) with effects and
 *  defects: `.fused` must give exactly the plain stream's output and effect log; `.fusedPar(3)`
 *  its output. When the chain throws, all variants must die with the same error. */
class FuzzSuite extends munit.FunSuite:
  type Mk = (ZStream[Any, Nothing, Int], Ref[Vector[String]]) => ZStream[Any, Nothing, Int]
  final case class Run(out: List[Either[String, Int]], log: Vector[String]):
    def failed: Boolean = out.lastOption.exists(_.isLeft)
    def elements: List[Int] = out.collect { case Right(x) => x }

  def input(r: Random): ZStream[Any, Nothing, Int] =
    val xs = Array.fill(r.nextInt(300))(r.nextInt(66) - 5)
    ZStream.fromChunks(xs.grouped(1 + r.nextInt(20)).map(Chunk.fromArray).toSeq*)

  def run(mk: Mk, seed: Long): Run =
    val z = for
      log <- Ref.make(Vector.empty[String])
      out <- mk(input(Random(seed)), log).map(Right(_): Either[String, Int])
               .catchAllCause(c => ZStream.succeed(Left(c.dieOption.map(_.getMessage).getOrElse(c.prettyPrint)))).runCollect
      l   <- log.get
    yield Run(out.toList, l)
    Unsafe.unsafe(implicit u => Runtime.default.unsafe.run(z.timeoutFail(new RuntimeException("timeout"))(20.seconds)).getOrThrowFiberFailure())

  /** Effects of the main chain must match exactly, in order. ZIO's `zipWith` pulls both sides
   *  concurrently (`zipWithPar`), so a zipped side's effects (tags `z…`) may interleave
   *  differently and plain ZIO may pull that side ahead: per zipped side, the fused effects must
   *  be a prefix of the plain ones. */
  def sameEffects(fused: Vector[String], plain: Vector[String], code: String): Unit =
    val (fz, fm) = fused.partition(_.startsWith("z"))
    val (pz, pm) = plain.partition(_.startsWith("z"))
    // Where a zip ends, plain ZIO (which pulls both sides concurrently) and fused code may
    // differ by one upstream pull; elsewhere the main chain's effects must match exactly.
    if code.contains("zipWith(") then
      assert(fm.startsWith(pm) || pm.startsWith(fm), s"main-chain effects diverge\n$code\nfused $fm\nplain $pm")
      assert(math.abs(fm.size - pm.size) <= 64, s"main-chain effects differ by more than a chunk\n$code")
    else same("main-chain effects", fm, pm, code)
    def bySide(l: Vector[String]) = l.groupBy(_.takeWhile(_ != ':'))
    val (fs, ps) = (bySide(fz), bySide(pz))
    for (side, fl) <- fs do
      val pl = ps.getOrElse(side, Vector.empty)
      assert(pl.startsWith(fl), s"zipped side $side: fused effects are not a prefix of plain\n$code\nfused $fl\nplain $pl")

  /** Fails with the first position where `a` and `b` differ, and a little context. */
  def same[T](what: String, a: Seq[T], b: Seq[T], code: String): Unit =
    if a != b then
      val i = a.indices.find(i => i >= b.size || a(i) != b(i)).getOrElse(a.size)
      fail(s"$what differs at $i (fused ${a.size}, plain ${b.size})\n$code\nfused ${a.slice(i - 3, i + 4)}\nplain ${b.slice(i - 3, i + 4)}")

  var exactOnFailure = 0
  var failures = 0
  var lazier = 0

  for c <- FuzzCases.cases do
    test(s"case ${c.name}: ${c.code.take(100)}") {
      val r = Random(c.name.hashCode)
      for _ <- 0 until 12 do
        val seed = r.nextLong()
        val (p, f, par) = (run(c.plain, seed), run(c.fused, seed), run(c.par, seed))
        if !p.failed then
          same("output", f.out, p.out, c.code)
          sameEffects(f.log, p.log, c.code)
          same("fusedPar output", par.out, p.out, c.code)
        else
          // Plain code failed. Fused code evaluates lambdas only for the elements it needs, while
          // plain fs2 / ZIO map whole chunks at once: if the failing element lies past a `take`,
          // fused code can succeed. Otherwise both fail with the same error, and the elements
          // emitted before it may differ at chunk granularity (one is a prefix of the other).
          failures += 1
          for (v, name) <- List(f -> "fused", par -> "fusedPar") do
            if v.failed then assertEquals(v.out.last, p.out.last, s"$name: different error\n${c.code}")
            else lazier += 1
            val (a, b) = (v.elements, p.elements)
            assert(a.startsWith(b) || b.startsWith(a), s"$name: outputs diverge\n${c.code}\n$name $a\nplain $b")
          if f.failed && f.elements == p.elements then exactOnFailure += 1
    }

  override def afterAll(): Unit =
    println(s"zio fuzz: ${FuzzCases.cases.size} chains; on failure, fused output before the error was identical in $exactOnFailure/$failures runs; fused succeeded where plain failed (lazier) $lazier times")
